import{_ as s,C as t,o as n,c as o,E as a,a2 as d}from"./chunks/framework.Cm6XCzck.js";const l="/joinwell52/assets/saaw-2026/figures/05_en.png",c="/joinwell52/assets/saaw-2026/figures/06_en.png",u="/joinwell52/assets/saaw-2026/figures/07_en.png",p="/joinwell52/assets/saaw-2026/figures/08_en.png",w=JSON.parse('{"title":"Global Real Digital Workers & SaaW Commercial Landscape 2026-2","description":"","frontmatter":{"title":"Global Real Digital Workers & SaaW Commercial Landscape 2026-2","date":"2026-09-03","research_date":"2026-08-30","prepared_date":"2026-09-03","column":"industry-architecture","category":"daily","article_type":"comparative-study","edition":"research-center","research_question":"How does model capability become inspectable role-based delivery, and how should governance and pricing relate to that delivery?","summary":"Separating model capability from reliable delivery, this article examines evidence, authority, recovery, pricing structures and admission requirements for digital-worker roles.","cover":"/assets/covers/saaw-2026-part-2-cover.png","language":"en","series":"saaw-commercial-landscape-2026","series_part":2,"lifecycle":"Published","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-09-03-saaw-models-governance-pricing.md","filePath":"en/industry/2026-09-03-saaw-models-governance-pricing.md","lastUpdated":1788401658000}'),m={name:"en/industry/2026-09-03-saaw-models-governance-pricing.md"};function h(g,e,f,y,b,v){const r=t("ArticleCover"),i=t("ArticleTableScroll");return n(),o("div",null,[a(r,{image:"/assets/covers/saaw-2026-part-2-cover.png",kicker:"Industry Architecture · SaaW Landscape (2)",title:"Global Real Digital Workers & SaaW Commercial Landscape 2026-2",summary:"Separating model capability from reliable delivery, this article examines evidence, authority, recovery, pricing structures and admission requirements for digital-worker roles.",version:"SaaW 2026 · 2/3",languageHref:"/zh/industry/2026-09-03-saaw-models-governance-pricing",languageLabel:"中文版"}),a(i,{language:"en"}),e[0]||(e[0]=d(`<h1 id="global-real-digital-workers-saaw-commercial-landscape-2026-2" tabindex="-1">Global Real Digital Workers &amp; SaaW Commercial Landscape 2026-2 <a class="header-anchor" href="#global-real-digital-workers-saaw-commercial-landscape-2026-2" aria-label="Permalink to &quot;Global Real Digital Workers &amp; SaaW Commercial Landscape 2026-2&quot;">​</a></h1><h2 id="models-governance-pricing-and-capability-tiers" tabindex="-1">Models, Governance, Pricing, and Capability Tiers <a class="header-anchor" href="#models-governance-pricing-and-capability-tiers" aria-label="Permalink to &quot;Models, Governance, Pricing, and Capability Tiers&quot;">​</a></h2><p>Products may all write reports, change code or handle business processes while differing in delivery quality, failure handling and the final bill. Assessing readiness for a role requires more than a feature list: how does the model decide, how does the runtime constrain actions, and who accepts the result?</p><p>This volume uses our <strong>SaaW (Software as an Agent Worker)</strong> concept: software continuously delivers work under explicit responsibilities, permissions and governance rules. See <a href="https://joinwell52-ai.github.io/joinwell52/zh/industry/2026-08-10-saaw-software-as-an-agent-worker" target="_blank" rel="noreferrer">From SaaS to SaaW</a>. Volume 1 compares products and roles. Here we ask: <strong>Which model makes decisions? How are model errors contained? Are software and model costs separate? How do these capabilities support D1–D5 classification?</strong></p><h1 id="_1-models-are-not-interchangeable-processors" tabindex="-1">1. Models Are Not Interchangeable Processors <a class="header-anchor" href="#_1-models-are-not-interchangeable-processors" aria-label="Permalink to &quot;1. Models Are Not Interchangeable Processors&quot;">​</a></h1><p>Business facts and fixed tools can mask model differences in short generation, single functions and simple support. Continuous decisions amplify those differences in repository engineering, open research and long cross-system tasks.</p><p>The project team previously encountered severe unsupported fabrication in model testing. Such experience cannot permanently condemn newer versions, but it motivates one rule:</p><blockquote><p><strong>Supporting a model does not automatically qualify a digital worker for a role. A configuration with a history of serious fabrication must pass real role evaluations again.</strong></p></blockquote><p>The same model behaves differently in a chat window, a coding agent or a runtime with terminals, tests and checkpoints. The evaluation unit is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model</span></span>
<span class="line"><span>+ runtime</span></span>
<span class="line"><span>+ tools and sources of truth</span></span>
<span class="line"><span>+ context compression and memory</span></span>
<span class="line"><span>+ permissions and recovery</span></span>
<span class="line"><span>= worker configuration</span></span></code></pre></div><h2 id="_1-1-representative-product-model-transparency" tabindex="-1">1.1 Representative Product Model Transparency <a class="header-anchor" href="#_1-1-representative-product-model-transparency" aria-label="Permalink to &quot;1.1 Representative Product Model Transparency&quot;">​</a></h2><p>Transparency concerns disclosure of model choices and routing, not model quality or role capability. CodeFlowMu is our self-developed collaboration application/runtime and appears last alongside other products.</p><p>D1 denotes assistance; D2 predominantly preset automation; D3 autonomous task execution; D4 a sustained bounded role; D5 stronger authorization, acceptance and recovery.</p><table tabindex="0"><thead><tr><th>Product</th><th>Public Model / Routing</th><th>Transparency</th><th>Model-Cost Separation</th><th>Tier</th></tr></thead><tbody><tr><td>Salesforce / Agentforce</td><td>Multi-model stack; exact routing varies by tenant and release and is not disclosed as one fixed model.</td><td>Medium</td><td>Model cost is bundled into credits or flat access, not transparently separated.</td><td>D3</td></tr><tr><td>Microsoft / Copilot Studio / Microsoft 365 Copilot</td><td>Primarily GPT-family models with selectable models in some scenarios and external services.</td><td>Medium</td><td>Platform licensing plus credit meters; premium reasoning may add meters, so costs are partly separated.</td><td>D3</td></tr><tr><td>ServiceNow / Autonomous Workforce / AI Specialists</td><td>Now LLM plus third-party models; the platform is positioned as model- and cloud-agnostic.</td><td>Medium</td><td>Model and platform costs are generally bundled in enterprise contracts.</td><td>D4</td></tr><tr><td>Workday / Sana Agents / Agent System of Record</td><td>Gemini became the default model for Sana for Workday in 2026; other agents may use multiple models.</td><td>High</td><td>Credits meter agent work; model cost is not fully itemized.</td><td>D3</td></tr><tr><td>Glean / Glean Agents / Independent Agents</td><td>Supports broad frontier-model choice; routing is task- and tenant-dependent.</td><td>Medium</td><td>Generally bundled into enterprise contracts; model cost is not public as a separate line.</td><td>D4</td></tr><tr><td>Oracle / Fusion Agentic Applications</td><td>Supports Llama, Cohere, external industry models, and partner models.</td><td>High</td><td>The application platform and model/cloud consumption are partly separated.</td><td>D4</td></tr><tr><td>Google Cloud / Gemini Enterprise Agent Platform</td><td>Primarily Gemini models, with support for customer and open models.</td><td>Medium</td><td>Clearly separated.</td><td>D3 (Platform)</td></tr><tr><td>Cognition / Devin</td><td>Core Devin routing is not fully disclosed; the product ecosystem exposes multiple frontier models.</td><td>Medium</td><td>Model, compute, and software capabilities are bundled in quotas/ACUs.</td><td>D4</td></tr><tr><td>Sierra / Sierra Agents / Horizon Agents</td><td>Underlying model stack and routing are not disclosed.</td><td>Low</td><td>Model cost is fully bundled into outcome pricing.</td><td>D4</td></tr><tr><td>Factory / Droids / Missions</td><td>Multi-model router supporting Claude, Gemini, Kimi, MiniMax, BYOK, and local models.</td><td>High</td><td>BYOK enables clear separation of software and model costs.</td><td>D4</td></tr><tr><td>Harvey / Harvey</td><td>Publicly uses models from OpenAI, Anthropic, Google, Mistral, and others.</td><td>Medium</td><td>Models and platform are bundled.</td><td>D3</td></tr><tr><td>Bland AI / Voice AI Agents</td><td>Proprietary voice/dialog stack; the company says production calls do not rely on third-party frontier models.</td><td>Medium</td><td>Fully bundled.</td><td>D3</td></tr><tr><td>Laiye / Laiye Worker / WEP</td><td>Model-neutral routing lists DeepSeek-V4, Qwen3-Max, Kimi K2, Doubao 2.0 Pro and GLM-5.1; selection considers task, budget, latency and compliance.</td><td><strong>Very high</strong></td><td>Platform subscription, credits and enterprise-owned/private models can be partly separated.</td><td>D4 candidate (sustained role unverified)</td></tr><tr><td>Tencent / WorkBuddy</td><td>August 2026 official list includes Hy3, GLM-5.2/5.1, MiniMax-M3, Kimi-K2.7-Code/K2.6 and DeepSeek-V4-Flash/V4-Pro; custom OpenAI, Anthropic and Gemini integration.</td><td><strong>Very high</strong></td><td>Enterprise/custom models and private deployment allow model costs to be separated from software licensing.</td><td>D3</td></tr><tr><td>Alibaba / DingTalk / Wukong</td><td>Exact model names are not disclosed; premium tiers expose model configuration parameters.</td><td>Low</td><td>Seat and compute credits are partly separated.</td><td>D3</td></tr><tr><td>Baidu AI Cloud / Keyue Digital Employees</td><td>ERNIE / Baidu AI Cloud model stack.</td><td>High</td><td>Model and product package are bundled.</td><td>D2–D3</td></tr><tr><td>Deepexi / DeepWorks / FastAGI</td><td>Configurable multi-model stack with FastAGI as runtime/guardrail layer.</td><td>Medium</td><td>Model and platform costs can be partly separated by deployment.</td><td>D3</td></tr><tr><td>Langboat / LangClaw</td><td>Mengzi model family with configurable models.</td><td>Medium</td><td>Potentially partly separated; contract terms are not public.</td><td>D3</td></tr><tr><td>SAP / Joule / Joule Agents</td><td>SAP Business AI multi-model stack; different use cases can use different foundation models.</td><td>Medium</td><td>Software subscription and premium agent usage are partly separated.</td><td>D3</td></tr><tr><td>Dust / Dust Agents</td><td>20+ models including GPT, Claude, Gemini, Mistral, and DeepSeek.</td><td>High</td><td>Credits bundle model and work usage; not fully separated.</td><td>D3</td></tr><tr><td>Mistral AI / Agents API / Enterprise Workflows</td><td>Primarily Mistral models with enterprise hybrid deployment.</td><td>High</td><td>Platform and model calls can be metered separately.</td><td>D3 (Platform)</td></tr><tr><td>Relevance AI / AI Workforce</td><td>Multi-model with BYO LLM/API keys.</td><td>Medium</td><td>Explicitly separates agent Action fees from model/tool Vendor Credits.</td><td>D3 (Platform)</td></tr><tr><td>Torq / Socrates</td><td>Exact models are not fully disclosed; the platform meters AI Credits.</td><td>Medium</td><td>Models and agent actions are bundled into fixed credits.</td><td>D4</td></tr><tr><td>causaLens / Digital Worker Factory</td><td>Model-agnostic, deployable on customer-selected models and infrastructure; workflow, trusted facts, causal verification and deterministic gates are central.</td><td>High: model strategy is explicit, without a fixed default model</td><td>Runtime and model costs can be separated on customer infrastructure.</td><td>D4</td></tr><tr><td>CodeFlowMu / Author-developed product</td><td>Models reason; the runtime organizes team collaboration and work state. The current complete model/routing list was not verified.</td><td>Architecture responsibilities are public; current configuration list not uniformly disclosed</td><td>Current quotation and model-cost separation unverified.</td><td><strong>D4 (software engineering role)</strong></td></tr></tbody></table><h2 id="_1-2-four-commercial-model-structures" tabindex="-1">1.2 Four Commercial Model Structures <a class="header-anchor" href="#_1-2-four-commercial-model-structures" aria-label="Permalink to &quot;1.2 Four Commercial Model Structures&quot;">​</a></h2><p><img src="`+l+`" alt="Figure 05: Software and model cost structures"></p><p><em>Figure 05. Structural relationships only. Widths do not encode prices; deployments can combine patterns. Source: the author&#39;s synthesis of the corresponding analysis in this article and its listed references.</em></p><table tabindex="0"><thead><tr><th>Structure</th><th>Meaning</th><th>Examples</th></tr></thead><tbody><tr><td>Fully bundled</td><td>Customers pay per minute, conversation, result or plan without a visible model-cost line</td><td>Sierra, Bland, Intercom, Shulex</td></tr><tr><td>Seat + credits</td><td>Seats and agent usage are separate, while credits still bundle model costs</td><td>Microsoft, WorkBuddy, Wukong, Salesforce</td></tr><tr><td>Platform actions + model cost</td><td>Agent execution and model/tool consumption are metered separately</td><td>Relevance AI, Google Agent Platform</td></tr><tr><td>Bring your own model</td><td>Customer keys/private/local models can shift model costs to the customer; additional action/runtime fees depend on the plan</td><td>Factory, Relevance AI, enterprise-custom WorkBuddy, some UiPath/Laiye deployments</td></tr></tbody></table><p>Relevance AI illustrates the distinction: action fees cover agent execution, while Vendor Credits cover model/tool costs, with supplier-cost metering and customer keys described in its documentation. Separately explaining software value and model cost is a useful design for CodeFlowMu; actual charging still depends on the product plan.</p><h2 id="_1-3-why-real-engineering-amplifies-model-differences" tabindex="-1">1.3 Why Real Engineering Amplifies Model Differences <a class="header-anchor" href="#_1-3-why-real-engineering-amplifies-model-differences" aria-label="Permalink to &quot;1.3 Why Real Engineering Amplifies Model Differences&quot;">​</a></h2><p>A digital software worker must preserve:</p><ul><li>Repository structure and architectural constraints.</li><li>Consistency across files.</li><li>Tests, builds, dependencies and CI state.</li><li>Explicit user prohibitions.</li><li>Failure causes and prior repairs.</li><li>Git, worktree and branch state.</li><li>Completion criteria and supporting evidence.</li></ul><table tabindex="0"><thead><tr><th>Engineering task</th><th>Where differences appear</th></tr></thead><tbody><tr><td>Write a function or explain an error</td><td>Leading models may be close</td></tr><tr><td>Change several files compatibly</td><td>Global consistency matters more</td></tr><tr><td>Failure → diagnosis → repair → retest</td><td>Recovery and causal judgment diverge</td></tr><tr><td>Large refactoring/migration</td><td>Locally correct changes can damage the whole system</td></tr><tr><td>Multi-hour unattended work</td><td>Drift, forgotten constraints and repeated side effects dominate</td></tr></tbody></table><p>Factory Missions offers one response: acceptance contracts, feature lists, research notes and runtime rules are shared files; Workers start with fresh context, Validators check output, and an Orchestrator organizes continuation or rework.</p><p>Cognition also compares model cost with real engineering rollouts. In the study&#39;s August 2026 materials, Devin Desktop/CLI offered GPT-5.6 Sol and compared score against cost on tasks such as FrontierCode, rather than relying only on launch benchmarks.</p><blockquote><p><strong>Worker capability depends jointly on the model, runtime, tools and facts, state and recovery, and governance. A standalone model score does not measure role delivery.</strong></p></blockquote><h3 id="why-long-tasks-amplify-small-differences" tabindex="-1">Why Long Tasks Amplify Small Differences <a class="header-anchor" href="#why-long-tasks-amplify-small-differences" aria-label="Permalink to &quot;Why Long Tasks Amplify Small Differences&quot;">​</a></h3><p>An earlier error can enter later context as a supposed fact and influence planning and actions. Checks, retries and recovery can interrupt that propagation. Long-task evaluations must observe error accumulation, detection and correction rather than one benchmark score.</p><p>Models therefore belong in role-admission decisions.</p><h1 id="_2-rpa-agents-and-digital-worker-boundaries" tabindex="-1">2. RPA, Agents and Digital-Worker Boundaries <a class="header-anchor" href="#_2-rpa-agents-and-digital-worker-boundaries" aria-label="Permalink to &quot;2. RPA, Agents and Digital-Worker Boundaries&quot;">​</a></h1><p>RPA (Robotic Process Automation) usually executes predefined interface or system operations. Classification depends on the division of responsibility between models, workflows and runtimes.</p><table tabindex="0"><thead><tr><th>Type</th><th>Who decides the next step?</th><th>Capability</th><th>Typical risk</th></tr></thead><tbody><tr><td>Traditional automation</td><td>Programmer-defined</td><td>Executes stable fixed processes</td><td>Interface/rule changes break it</td></tr><tr><td>LLM + workflow</td><td>Model interprets; workflow determines most paths</td><td>Natural-language entry and limited exceptions</td><td>A workflow bot may be marketed as an employee</td></tr><tr><td>Agentic execution</td><td>Model plans, selects tools and adapts</td><td>Completes a complex task</td><td>Drift, repeated side effects, confident errors</td></tr><tr><td>Digital worker</td><td>Model/runtime maintain role, tasks and state</td><td>Sustained cross-cycle work</td><td>Model changes alter role capability</td></tr><tr><td>High-trust software worker</td><td>Work governance contains errors</td><td>Can be authorized for production business work</td><td>Complete public evidence remains scarce</td></tr></tbody></table><p>RPA is useful in high-risk writes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model: understanding and planning</span></span>
<span class="line"><span>+ rules / business systems: facts and boundaries</span></span>
<span class="line"><span>+ automation / APIs: deterministic execution</span></span>
<span class="line"><span>+ humans: exceptions and accountability decisions</span></span></code></pre></div><p>The question is whether RPA acts as the worker&#39;s hands or determines the entire product&#39;s behavior.</p><h1 id="_3-how-commercial-products-contain-hallucination" tabindex="-1">3. How Commercial Products Contain Hallucination <a class="header-anchor" href="#_3-how-commercial-products-contain-hallucination" aria-label="Permalink to &quot;3. How Commercial Products Contain Hallucination&quot;">​</a></h1><p>Models can generate unsupported content. Enterprise systems must reduce errors, detect them and contain their effects on business actions.</p><table tabindex="0"><thead><tr><th>Defense</th><th>Techniques</th><th>Purpose</th></tr></thead><tbody><tr><td>Grounding</td><td>CRM, ERP, knowledge, retrieval, business APIs</td><td>Constrain business claims with records</td></tr><tr><td>Scope</td><td>Roles, topics, skills, tool allowlists</td><td>Restrict questions and actions</td></tr><tr><td>Identity/least privilege</td><td>Role permissions, access control, agent identities</td><td>Limit authority despite model intent</td></tr><tr><td>Action schemas</td><td>Parameterized tools, business objects, deterministic processes</td><td>Validate parameters, permissions and rules</td></tr><tr><td>Call-time approval</td><td>One-time tokens, human approvals, escalation</td><td>Separate capability from current permission</td></tr><tr><td>Runtime evaluation</td><td>Simulation, regression, output checks, injection detection</td><td>Find deviations before and during operation</td></tr><tr><td>Observability/audit</td><td>File, command and API logs; cost/outcome dashboards</td><td>Diagnose, assign responsibility, stop and improve</td></tr><tr><td>Recovery/rollback</td><td>Checkpoints, versions, compensation, idempotency</td><td>Avoid duplicate writes and lost responsibility</td></tr></tbody></table><h2 id="_3-1-what-enterprise-governance-already-does" tabindex="-1">3.1 What Enterprise Governance Already Does <a class="header-anchor" href="#_3-1-what-enterprise-governance-already-does" aria-label="Permalink to &quot;3.1 What Enterprise Governance Already Does&quot;">​</a></h2><ul><li>Salesforce constrains models with CRM facts, permissions, actions, monitoring and audit.</li><li>ServiceNow discovers, observes, governs and disables misbehaving agents, recording files, commands and API calls.</li><li>Glean provides request-level checks, identities, scoped credentials, checkpoints, evaluations, approvals and rollback.</li><li>UiPath combines injection/sensitive-data defenses, mandatory human intervention and deterministic robot execution.</li><li>Oracle supplies roles, approval hierarchies, transactional context, shared memory and action history.</li><li>Torq governs security tools, policy, approvals and remediation audit.</li></ul><p>These are real controls, mainly over assets, security, access and runtime behavior.</p><h2 id="_3-2-why-work-governance-adds-further-questions" tabindex="-1">3.2 Why Work Governance Adds Further Questions <a class="header-anchor" href="#_3-2-why-work-governance-adds-further-questions" aria-label="Permalink to &quot;3.2 Why Work Governance Adds Further Questions&quot;">​</a></h2><p>Open knowledge work must also establish:</p><ul><li>Which source supports a market number, legal conclusion or technical judgment?</li><li>Is it a source fact, inference or unproven assumption?</li><li>How are conflicting sources preserved?</li><li>Who reviews independently and accepts the conclusion?</li><li>Does formal responsibility survive model changes or process restarts?</li></ul><blockquote><p><strong>Agent governance addresses safe software operation. Work governance also addresses why a conclusion is valid and who is responsible for it.</strong></p></blockquote><h2 id="_3-3-five-reliability-layers" tabindex="-1">3.3 Five Reliability Layers <a class="header-anchor" href="#_3-3-five-reliability-layers" aria-label="Permalink to &quot;3.3 Five Reliability Layers&quot;">​</a></h2><p><img src="`+c+'" alt="Figure 06: Five reliability layers and their boundaries"></p><p><em>Figure 06. Different defenses answer different questions. This is not a vendor score or a claim that one product implements all five layers. Source: the author&#39;s synthesis of the corresponding analysis in this article and its listed references.</em></p><table tabindex="0"><thead><tr><th>Layer</th><th>Techniques</th><th>Question addressed</th><th>Remaining limit</th></tr></thead><tbody><tr><td>1. Prompt guardrails</td><td>System prompts, prohibited terms, formats</td><td>Reduces obvious boundary violations</td><td>Confident fabrication remains possible</td></tr><tr><td>2. Grounding</td><td>Retrieval, enterprise knowledge, CRM/ERP, APIs</td><td>Grounds business facts outside model memory</td><td>Does not guarantee correct reasoning</td></tr><tr><td>3. Agent governance</td><td>Identity, permissions, allowlists, approval, audit</td><td>Controls actions and authority</td><td>Does not prove delivery claims</td></tr><tr><td>4. Decision verification</td><td>Trusted Facts, structured claims, deterministic gates, judges</td><td>Checks whether decisions follow trusted facts and rules</td><td>Does not establish complete organizational accountability</td></tr><tr><td>5. Work governance</td><td>Formal tasks, delivery, fact checking, observation, acceptance authority, continuity</td><td>Establishes responsibility, accepted results and valid state</td><td>Requires organizational adoption and institutional fit</td></tr></tbody></table><p>causaLens describes Layer-4 mechanisms: Trusted Facts retain system-computed evidence; Structured Decision Claims organize facts, rules and recommendations; a Deterministic Verification Gate checks rules before model evaluation and returns failed outputs to execution.</p><p>This adds checks on decision support beyond retrieval-augmented generation (RAG) and prompts. <strong>Fact checking and independent evaluation already appear in commercial technical designs.</strong></p><p>TMPA (Textual Multi-Agent Process Architecture), used by CodeFlowMu, also asks how checked judgments become traceable formal work results through tasks, delivery, acceptance and responsibility facts.</p><h2 id="_3-4-comparing-governance-mechanisms" tabindex="-1">3.4 Comparing Governance Mechanisms <a class="header-anchor" href="#_3-4-comparing-governance-mechanisms" aria-label="Permalink to &quot;3.4 Comparing Governance Mechanisms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Product</th><th>Grounding</th><th>Action authority</th><th>Human approval</th><th>Runtime evaluation</th><th>Deterministic verification</th><th>Independent Judge/EVAL</th><th>Durable responsibility facts</th></tr></thead><tbody><tr><td>ServiceNow</td><td>Strong</td><td>Strong</td><td>Strong</td><td>Very strong</td><td>Partial</td><td>Evaluation system</td><td>Weak/platform-local</td></tr><tr><td>Glean</td><td>Strong</td><td>Per-request/action checks</td><td>Strong</td><td>Strong</td><td>Partial</td><td>Alignment/evals</td><td>Weak</td></tr><tr><td>Relevance AI</td><td>Connector-dependent</td><td>Edge configuration</td><td>Strong</td><td>Task View/logs</td><td>Weak</td><td>Weak</td><td>Task-level</td></tr><tr><td>causaLens</td><td>Very strong</td><td>Strong</td><td>Strong</td><td>Strong</td><td>Very strong</td><td>Judge Agent</td><td>Medium</td></tr><tr><td>Factory</td><td>Code/test facts</td><td>Tools/sandbox</td><td>User takeover</td><td>Validator</td><td>Validation contract</td><td>Validator</td><td>Project-task level</td></tr><tr><td>SAP</td><td>SAP business facts</td><td>Enterprise permissions</td><td>Strong</td><td>Enterprise monitoring</td><td>Business rules/processes</td><td>Partial</td><td>Platform-process level</td></tr><tr><td>CodeFlowMu</td><td>Tasks, reports and engineering evidence</td><td>Role permissions and governance decisions</td><td>Human approval entry</td><td>Public regression and implementation cases</td><td>Fixed-input state/rule checks</td><td>Separate QA; EVAL observes alongside execution</td><td>Persistent tasks, reports, reviews and recovery records</td></tr></tbody></table><p>These are qualitative comparisons from public mechanisms, not uniform test scores. CodeFlowMu evidence includes public collaboration and V1.8.0 results in I1.0. Role authorization checks do not prove call-time authorization for every external action.</p><h1 id="_4-why-support-and-open-research-differ-in-delivery-difficulty" tabindex="-1">4. Why Support and Open Research Differ in Delivery Difficulty <a class="header-anchor" href="#_4-why-support-and-open-research-differ-in-delivery-difficulty" aria-label="Permalink to &quot;4. Why Support and Open Research Differ in Delivery Difficulty&quot;">​</a></h1><p>Support and enterprise transactions have clear facts, bounded actions and measurable completion: orders, logistics and refund eligibility come from systems and rules; operations include lookup, address changes, refunds, tickets and escalation.</p><p>Open research has no single truth database. It requires source selection, quality assessment, conflict handling, fact/inference separation and responsibility for conclusions. Retrieval establishes what was found, not whether a conclusion is correct.</p><table tabindex="0"><thead><tr><th>Work</th><th>Fact certainty</th><th>Action space</th><th>Completion criterion</th><th>Fit for current agents</th></tr></thead><tbody><tr><td>Support/orders/employee self-service</td><td>High</td><td>Small</td><td>Clear</td><td>Very high</td></tr><tr><td>Sales/procurement/contract triage</td><td>Medium</td><td>Medium</td><td>Partly measurable</td><td>Medium-high</td></tr><tr><td>Software engineering</td><td>Medium</td><td>Large</td><td>Partly verified by tests/review</td><td>Medium-high, model-sensitive</td></tr><tr><td>Business research/strategy</td><td>Low</td><td>Large</td><td>Hard to verify automatically</td><td>Low</td></tr><tr><td>High-risk finance/legal decisions</td><td>Medium</td><td>Medium</td><td>Major liability</td><td>Human final authorization required</td></tr></tbody></table><h1 id="_5-pricing-units-reveal-the-delivery-unit" tabindex="-1">5. Pricing Units Reveal the Delivery Unit <a class="header-anchor" href="#_5-pricing-units-reveal-the-delivery-unit" aria-label="Permalink to &quot;5. Pricing Units Reveal the Delivery Unit&quot;">​</a></h1><p><img src="'+u+`" alt="Figure 07: Pricing units and actual delivery"></p><p><em>Figure 07. Units are grouped into access, activity, capacity and outcomes. Arrows describe different delivery objects, not a universal migration or proof that outcome pricing dominates. Source: the author&#39;s synthesis of the corresponding analysis in this article and its listed references.</em></p><table tabindex="0"><thead><tr><th>Pricing Unit</th><th>What the Customer Buys</th><th>Examples</th></tr></thead><tbody><tr><td>Seat</td><td>Access for a human user</td><td>M365 Copilot, Wukong, WorkBuddy</td></tr><tr><td>Credits</td><td>Agent/model capacity</td><td>Microsoft, WorkBuddy, SAP, Torq</td></tr><tr><td>Action</td><td>One tool/business action</td><td>Salesforce, Relevance AI, SAP</td></tr><tr><td>Conversation</td><td>One customer interaction</td><td>Salesforce, Ada, Decagon</td></tr><tr><td>Resolution</td><td>A validated solved issue</td><td>Zendesk, Intercom, Yellow.ai</td></tr><tr><td>Lead</td><td>One researched/contacted prospect</td><td>11x, Artisan</td></tr><tr><td>Minute</td><td>Voice labor</td><td>Bland, PolyAI, Parloa</td></tr><tr><td>Agent Compute Unit</td><td>Planning, tools, code, and runtime resources</td><td>Devin</td></tr><tr><td>Outcome</td><td>Retention, sale, resolution, collection, etc.</td><td>Sierra</td></tr></tbody></table><h3 id="pricing-changes-highlighted-in-the-2026-study" tabindex="-1">Pricing Changes Highlighted in the 2026 Study <a class="header-anchor" href="#pricing-changes-highlighted-in-the-2026-study" aria-label="Permalink to &quot;Pricing Changes Highlighted in the 2026 Study&quot;">​</a></h3><ul><li><strong>HubSpot:</strong> Customer Agent at <strong>$0.50/successful resolution</strong>; Prospecting Agent at <strong>$1/recommended outreach lead</strong>.</li><li><strong>Intercom Fin:</strong> <strong>$0.99/outcome</strong> (resolution, procedure handoff or disqualification); successful sales qualification <strong>$9.99</strong>. Failure or a user-requested human handoff does not incur an outcome fee.</li><li><strong>Zendesk:</strong> From May 2026, Automated Resolution/Resolution Allowance meters successful AI resolutions without escalation, with complexity tiers.</li><li><strong>Relevance AI:</strong> Platform action fees and model/tool Vendor Credits are separate. The cited documentation lists <strong>$80/additional 1,000 Actions</strong>, supplier-cost pass-through and customer keys.</li><li><strong>Laiye Worker:</strong> RMB39/199 plans, credits and enterprise governance/private deployment illustrate China&#39;s hybrid structure.</li><li><strong>WorkBuddy Enterprise:</strong> RMB198/316 per user/month, credits and private deployment show continued seat pricing plus agent usage.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Software access</span></span>
<span class="line"><span>→ human productivity</span></span>
<span class="line"><span>→ agent actions</span></span>
<span class="line"><span>→ digital work capacity</span></span>
<span class="line"><span>→ verifiable business outcomes</span></span></code></pre></div><p>Outcome charging is not yet universal. Many products still use seats, credits and enterprise contracts.</p><h1 id="_6-capability-tiers-and-sample-totals" tabindex="-1">6. Capability Tiers and Sample Totals <a class="header-anchor" href="#_6-capability-tiers-and-sample-totals" aria-label="Permalink to &quot;6. Capability Tiers and Sample Totals&quot;">​</a></h1><p>The same Volume 1 comparison contains <strong>55 entries: 54 original commercial samples plus CodeFlowMu</strong>. Capability and paid commercial status are separate; D2–D3 boundary cases retain their labels.</p><table tabindex="0"><thead><tr><th>Tier/label</th><th>Count</th><th>Examples</th><th>Conclusion</th></tr></thead><tbody><tr><td>D1</td><td>0 in main table</td><td>Pure Q&amp;A/search excluded</td><td>Does not imply absence from the market</td></tr><tr><td>D2</td><td>0 standalone</td><td>Boundary entries appear below</td><td>Boundaries are not forced into D2</td></tr><tr><td>D2–D3 boundary</td><td><strong>9</strong></td><td>Baidu Keyue, Robin, Juro, LayerX</td><td>Planning versus preset workflow needs product-level assessment</td></tr><tr><td>D3</td><td><strong>36</strong></td><td>Salesforce, Microsoft, UiPath, SAP, Zendesk, Intercom, WorkBuddy, Wukong</td><td>Largest sample category, including 3 platforms</td></tr><tr><td>D4</td><td><strong>9</strong></td><td>ServiceNow, Glean, Oracle, Devin, Sierra, Factory, Torq, causaLens, <strong>CodeFlowMu</strong></td><td>Public-evidence initial assessments; CodeFlowMu is limited to software engineering</td></tr><tr><td>D4 candidate</td><td><strong>1</strong></td><td>Laiye Worker</td><td>Execution/routing evidence exists; sustained role needs verification</td></tr><tr><td>D5</td><td>0</td><td>No award</td><td>Public evidence does not fully cover the report&#39;s conditions</td></tr><tr><td>Total</td><td><strong>55</strong></td><td>54 commercial samples + 1 self-developed product</td><td>Mutually exclusive labels</td></tr></tbody></table><p>Counts describe sampling and classification, not market share. Platform configurations may occupy different tiers.</p><h2 id="_6-1-role-capability-versus-high-trust-governance" tabindex="-1">6.1 Role Capability Versus High-Trust Governance <a class="header-anchor" href="#_6-1-role-capability-versus-high-trust-governance" aria-label="Permalink to &quot;6.1 Role Capability Versus High-Trust Governance&quot;">​</a></h2><ul><li>Devin spans repositories but needs large tasks decomposed and ambiguous architecture clarified.</li><li>Sierra spans days/weeks, with limited model, evidence and recovery disclosure.</li><li>ServiceNow/Oracle have strong governance but focus less on evidencing open knowledge conclusions.</li><li>Factory supports long tasks and multiple models, while acceptance is mainly engineering validation.</li><li>Glean has identity, credentials, evaluations and rollback; customer-built agents vary.</li><li>Torq acknowledges nondeterminism and recommends fixed workflows when determinism is required.</li><li>causaLens has trusted facts, deterministic verification and judges, but public evidence is incomplete for cross-task formal responsibility, side-effect receipts and final governance-state reconstruction.</li></ul><h1 id="_7-model-admission-for-digital-workers" tabindex="-1">7. Model Admission for Digital Workers <a class="header-anchor" href="#_7-model-admission-for-digital-workers" aria-label="Permalink to &quot;7. Model Admission for Digital Workers&quot;">​</a></h1><p><img src="`+p+`" alt="Figure 08: Model admission evaluates the configuration"></p><p><em>Figure 08. Role risk → capability profile → model/host/tool/runtime evaluation → allow, restrict, require review or reject. This is a proposed framework, not completed benchmark results. Source: the author&#39;s synthesis of the corresponding analysis in this article and its listed references.</em></p><p>A runtime should maintain role requirements and configuration admission, rather than only <code>model = X</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Role risk and task type</span></span>
<span class="line"><span>→ Required capability profile</span></span>
<span class="line"><span>   Facts / instructions / long tasks / tools / recovery</span></span>
<span class="line"><span>→ Evaluate model + host + tools + runtime</span></span>
<span class="line"><span>→ Allow / restrict / require independent review / reject</span></span></code></pre></div><p>Admission should produce actionable conclusions rather than only an aggregate score:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Configuration A</span></span>
<span class="line"><span>Information organization: allow</span></span>
<span class="line"><span>Content drafts: allow with review</span></span>
<span class="line"><span>Business research conclusions: restrict</span></span>
<span class="line"><span>Production code changes: independent tests and review required</span></span>
<span class="line"><span>High-risk external actions: reject</span></span></code></pre></div><h2 id="_7-1-model-capability-profile" tabindex="-1">7.1 Model Capability Profile <a class="header-anchor" href="#_7-1-model-capability-profile" aria-label="Permalink to &quot;7.1 Model Capability Profile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Real evaluation question</th></tr></thead><tbody><tr><td>Factual reliability</td><td>Does it admit uncertainty or invent sources, files and API results?</td></tr><tr><td>Long-task stability</td><td>Does it drift after 30 minutes, two hours or multiple days?</td></tr><tr><td>Tool use</td><td>Are tool choice, parameters and order correct?</td></tr><tr><td>Instruction retention</td><td>Does it retain prohibitions on editing/publishing and requirements to verify?</td></tr><tr><td>Recovery</td><td>Does it resume correctly after tool failure, host restart or model change?</td></tr><tr><td>Self-checking</td><td>Does it detect contradictions rather than defend earlier conclusions?</td></tr><tr><td>Evidence discipline</td><td>Does it separate external facts, tool results, inference and assumptions?</td></tr><tr><td>High-risk actions</td><td>Should it receive write authority or only propose actions?</td></tr></tbody></table><p>Example minimum role requirements:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Support lookup: moderate reasoning + strong facts</span></span>
<span class="line"><span>Software development: repository understanding + tools + tests + recovery</span></span>
<span class="line"><span>Business research: source discipline + conflict handling + independent review</span></span>
<span class="line"><span>Critical finance/legal action: strong model + deterministic rules + human final authorization</span></span></code></pre></div><p>Model substitution must not be confused with equivalent capability.</p><h1 id="_8-volume-conclusion" tabindex="-1">8. Volume Conclusion <a class="header-anchor" href="#_8-volume-conclusion" aria-label="Permalink to &quot;8. Volume Conclusion&quot;">​</a></h1><p>The competitive questions are who can:</p><ol><li>Constrain model uncertainty within facts, tools and authorization.</li><li>Admit different models only to suitable roles.</li><li>Explain software costs, model costs and delivery clearly.</li><li>Reconstruct accountability after failure rather than merely retry an API.</li><li>Turn completion claims into evidenced, independently reviewable delivery.</li></ol><p>Volume 3 examines public implementations of identities, task ledgers, pre-action authorization, recovery, phone supervision and installation, then develops CodeFlowMu&#39;s product direction.</p><h1 id="_9-references" tabindex="-1">9. References <a class="header-anchor" href="#_9-references" aria-label="Permalink to &quot;9. References&quot;">​</a></h1><p>Product and pricing information follows the original research scope; current vendor terms govern actual purchases and configurations. Tiers and qualitative comparisons are not uniform product tests.</p><ul><li><a href="https://causalens.com/our-digital-worker-factory" target="_blank" rel="noreferrer">causaLens Digital Worker Factory</a></li><li><a href="https://causalens.com/the-reliability-features" target="_blank" rel="noreferrer">causaLens reliability</a></li><li><a href="https://factory.ai/news/missions-architecture" target="_blank" rel="noreferrer">Factory Missions architecture</a></li><li><a href="https://www.servicenow.com/docs/r/intelligent-experiences/mon-ai-evaluation-metrics-reference.html" target="_blank" rel="noreferrer">ServiceNow evaluation metrics</a></li><li><a href="https://www.glean.com/ai-agents/agent-governance" target="_blank" rel="noreferrer">Glean agent governance</a></li><li><a href="https://relevanceai.com/docs/get-started/pricing" target="_blank" rel="noreferrer">Relevance AI pricing</a></li><li><a href="https://relevanceai.com/docs/build/workforces/workforce-features/approvals-and-escalations" target="_blank" rel="noreferrer">Relevance AI approvals</a></li><li><a href="https://www.intercom.com/help/en/articles/8205718-fin-ai-agent-outcomes" target="_blank" rel="noreferrer">Intercom Fin outcomes</a></li><li><a href="https://support.zendesk.com/hc/en-us/articles/9570369117338-About-automated-resolution-tiers" target="_blank" rel="noreferrer">Zendesk resolution tiers</a></li><li><a href="https://www.hubspot.com/company-news/hubspots-customer-agent-and-prospecting-agent-now-you-pay-when-the-task-is-complete" target="_blank" rel="noreferrer">HubSpot outcome pricing</a></li><li><a href="https://laiye.com/product/worker" target="_blank" rel="noreferrer">Laiye Worker</a></li><li><a href="https://cloud.tencent.com/document/product/1831/134445" target="_blank" rel="noreferrer">WorkBuddy model configuration</a></li><li><a href="https://cloud.tencent.com/document/product/1831/134333" target="_blank" rel="noreferrer">WorkBuddy pricing</a></li><li><a href="https://devin.ai/blog/gpt-5-6-sol-price-drop" target="_blank" rel="noreferrer">Devin GPT-5.6 Sol engineering cost comparison</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">CodeFlowMu public project description</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/zh/digital-employee/2026-08-18-cursor-ai-development-team" target="_blank" rel="noreferrer">CodeFlowMu development collaboration</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/zh/publications/implementation-case-i1.0/part-02.md" target="_blank" rel="noreferrer">CodeFlowMu V1.8.0 I1.0 implementation evidence</a></li></ul>`,92))])}const A=s(m,[["render",h]]);export{w as __pageData,A as default};
